package com.finance.model;
import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.mapping.Document; import java.time.LocalDate;
@Document("recurringTransactions") public class RecurringTransaction { @Id private String id; private String userId; private String type; private String category; private String description; private long amountPaise; private String frequency; private LocalDate nextDate; private boolean active=true; public String getId(){return id;} public void setId(String v){id=v;} public String getUserId(){return userId;} public void setUserId(String v){userId=v;} public String getType(){return type;} public void setType(String v){type=v;} public String getCategory(){return category;} public void setCategory(String v){category=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public long getAmountPaise(){return amountPaise;} public void setAmountPaise(long v){amountPaise=v;} public String getFrequency(){return frequency;} public void setFrequency(String v){frequency=v;} public LocalDate getNextDate(){return nextDate;} public void setNextDate(LocalDate v){nextDate=v;} public boolean isActive(){return active;} public void setActive(boolean v){active=v;} }
